<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        PARTITION</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> product_type_id</span></span>
